/**
 * Flagship projects: one per degree term and one per Programming month.
 *
 * Coursework proves you studied; a flagship proves you can build. Each is
 * picked to be the project an engineer in that field would stop scrolling
 * for — hard, finished, public, and measured — and to leave you ready for a
 * starter internship by the time the term ends. The bars are numbers, not
 * adjectives, and wherever one exists the judge is someone else's test suite:
 * riscv-tests, the Writing a C Compiler tests, Maelstrom, Lean's kernel,
 * MIT's Raft tests, a physical load cell.
 *
 * Every flagship is checked on GitHub the way builds are (js/github.js): a
 * public repo you own, a write-up with a photo or video, a "what broke"
 * section, several commits, and the numbers its bar asks for.
 *
 *   track      a degree id, or 'cp'
 *   term       0–5 for a degree; month 1–4 for cp
 *   uses       the courses it draws on
 *   milestones checkpoints you tick as you go (your word, like degree weeks)
 *   bar        what "done" means, measurably
 *   options    for capstones: one route per concentration; you pick one
 *   post       a LinkedIn post to fill in with your real numbers
 *   bullet     the resume line it earns
 */

const need = (label, re, min = 1) => ({ label, re, min });
const file = (label, re) => ({ label, re });
const L = (name, url) => ({ name, url });
const NUM = (label, min = 3) => need(label, /\b\d+(?:\.\d+)?\s*(?:%|ms|µs|us|ns|s|x|×|mm|kg|n|hz|khz|mhz|db|v|mv|a|ma|w|°c|k|ops\/s|req\/s|mb|gb)?\b/i, min);

