export const flagshipById = id => FLAGSHIPS.find(f => f.id === id) || null;
export const flagshipsFor = track => FLAGSHIPS.filter(f => f.track === track).sort((a, b) => a.term - b.term);
/** The flagship for a degree term (0-based) or a cp month (1-based). */
export const flagshipAt = (track, term) => FLAGSHIPS.find(f => f.track === track && f.term === term) || null;
